mapper.select:
select distinct sum(sum(session_complete) filter (where event in ('COMPLETED'))) over () as 总会话完成数, sum(sum(queue_abort) filter (where event in ('QUEUE_ABANDONED'))) over () as 总排队放弃数, avg(avg(queue_duration) filter (where event in ('ASSIGNED'))) over () as 总平均排队时长, avg(avg(session_duration) filter (where event in ('COMPLETED'))) over () as 总平均会话时长, sum(last(realtime_session_count, time) filter (where event in ('COMPLETED', 'STARTED'))) over () as 总实时会话数, sum(last(realtime_session_queued_count, time) filter (where event in ('QUEUED', 'QUEUE_ABANDONED'))) over () as 总实时排队数, sum(last(realtime_session_locked_count, time) filter (where event in ('LOCKED', 'UNLOCKED'))) over () as 总实时会话锁定数, sum(last(realtime_session_assigned_count, time) filter (where event in ('ASSIGNED', 'COMPLETED'))) over () as 总实时接待会话数, sum(last(realtime_session_robot_count, time) filter (where event in ('ROBOT_MANAGED', 'ROBOT_CANCELLED'))) over () as 总实时托管会话数 from session_event_new where time >= now() - interval '1 day' and enterprise_id = 8001678 and qno in
#{qno}
and cno in
#{cno}
group by cno, qno, app;

select *
from session_event_new order by time asc
limit #{size} offset #{offset}
